import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import Icon from '../../../components/AppIcon';
import { useToast } from '../../../contexts/ToastContext';

const BuilderApplications = () => {
    const { addToast } = useToast();
    const [applications, setApplications] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [filterStatus, setFilterStatus] = useState('all');

    useEffect(() => {
        fetchApplications();
    }, []);

    const fetchApplications = async () => {
        setIsLoading(true);
        try {
            const data = await supabaseService.getBuilderApplications();
            setApplications(data || []);
        } catch (err) {
            addToast("Failed to load applications", "error");
        } finally {
            setIsLoading(false);
        }
    };

    const handleUpdateStatus = async (id, status) => {
        try {
            await supabaseService.updateBuilderApplicationStatus(id, status);
            setApplications(applications.map(app => app.id === id ? { ...app, status } : app));
            addToast(`Application marked as ${status}`, "success");
        } catch (err) {
            addToast("Failed to update status", "error");
        }
    };

    const handleApprove = async (app) => {
        try {
            await supabaseService.approveAsBuilder(app.id, app.email);
            setApplications(applications.map(a => a.id === app.id ? { ...a, status: 'accepted' } : a));
            addToast(`${app.full_name} is now an official LUC Builder!`, "success");
        } catch (err) {
            addToast("Failed to approve as builder", "error");
        }
    };

    const filteredApps = applications.filter(app => 
        filterStatus === 'all' || app.status === filterStatus
    );

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="flex items-center gap-3">
                    <div className="p-3 bg-secondary/10 rounded-2xl">
                        <Icon name="Users" className="text-secondary" size={24} />
                    </div>
                    <div>
                        <h2 className="text-2xl font-black text-slate-900 dark:text-white uppercase italic tracking-tight">Elite <span className="text-secondary">Recruitment.</span></h2>
                        <p className="text-sm text-slate-500 font-medium">Reviewing Yobe's top tech talent for the LUC Build Cycle.</p>
                    </div>
                </div>

                <div className="flex items-center gap-2 bg-slate-100 dark:bg-white/5 p-1 rounded-2xl">
                    {['all', 'pending', 'reviewing', 'accepted'].map(status => (
                        <button 
                            key={status}
                            onClick={() => setFilterStatus(status)}
                            className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${filterStatus === status ? 'bg-white dark:bg-slate-800 text-secondary shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                        >
                            {status}
                        </button>
                    ))}
                </div>
            </div>

            <div className="bg-card border border-border rounded-[2.5rem] overflow-hidden shadow-sm">
                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead className="bg-muted/50 border-b border-border">
                            <tr>
                                <th className="px-8 py-4 text-[10px] font-black uppercase tracking-widest text-slate-500">Applicant</th>
                                <th className="px-8 py-4 text-[10px] font-black uppercase tracking-widest text-slate-500">Proposed Role</th>
                                <th className="px-8 py-4 text-[10px] font-black uppercase tracking-widest text-slate-500">Portfolio</th>
                                <th className="px-8 py-4 text-[10px] font-black uppercase tracking-widest text-slate-500">Status</th>
                                <th className="px-8 py-4 text-[10px] font-black uppercase tracking-widest text-slate-500 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border">
                            {isLoading ? (
                                <tr><td colSpan="5" className="px-8 py-12 text-center text-slate-400 italic">Scanning database for talent...</td></tr>
                            ) : filteredApps.length === 0 ? (
                                <tr><td colSpan="5" className="px-8 py-12 text-center text-slate-400 italic">No applications found in this category.</td></tr>
                            ) : filteredApps.map(app => (
                                <tr key={app.id} className="hover:bg-muted/30 transition-colors">
                                    <td className="px-8 py-6">
                                        <div>
                                            <p className="text-sm font-black text-slate-900 dark:text-white uppercase italic">{app.full_name}</p>
                                            <p className="text-[10px] text-slate-500 font-medium">{app.email}</p>
                                        </div>
                                    </td>
                                    <td className="px-8 py-6">
                                        <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-tighter ${
                                            app.role === 'dev' ? 'bg-blue-500/10 text-blue-500' :
                                            app.role === 'design' ? 'bg-purple-500/10 text-purple-500' :
                                            app.role === 'content' ? 'bg-orange-500/10 text-orange-500' :
                                            'bg-emerald-500/10 text-emerald-500'
                                        }`}>
                                            {app.role === 'dev' ? 'Architect' : app.role === 'design' ? 'Visionary' : app.role === 'content' ? 'Evangelist' : 'Manager'}
                                        </span>
                                    </td>
                                    <td className="px-8 py-6">
                                        <a 
                                            href={app.portfolio_url} 
                                            target="_blank" 
                                            rel="noopener noreferrer"
                                            className="inline-flex items-center gap-2 text-[10px] font-black text-primary uppercase tracking-widest hover:underline"
                                        >
                                            View Craft <Icon name="ExternalLink" size={12} />
                                        </a>
                                    </td>
                                    <td className="px-8 py-6">
                                        <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-widest ${
                                            app.status === 'accepted' ? 'bg-emerald-500/10 text-emerald-500' :
                                            app.status === 'rejected' ? 'bg-red-500/10 text-red-500' :
                                            app.status === 'reviewing' ? 'bg-blue-500/10 text-blue-500' :
                                            'bg-amber-500/10 text-amber-500'
                                        }`}>
                                            {app.status}
                                        </span>
                                    </td>
                                    <td className="px-8 py-6 text-right space-x-2">
                                        {app.status !== 'accepted' && (
                                            <button 
                                                onClick={() => handleApprove(app)}
                                                className="px-4 py-1.5 bg-emerald-500 text-white text-[10px] font-black uppercase tracking-widest rounded-lg shadow-lg shadow-emerald-500/20 hover:scale-105 active:scale-95 transition-all"
                                            >
                                                Approve
                                            </button>
                                        )}
                                        <select 
                                            value={app.status}
                                            onChange={(e) => handleUpdateStatus(app.id, e.target.value)}
                                            className="text-[10px] font-black uppercase tracking-tight bg-slate-100 dark:bg-white/5 border-none rounded-lg px-3 py-1.5 outline-none"
                                        >
                                            <option value="pending">Pending</option>
                                            <option value="reviewing">Reviewing</option>
                                            <option value="accepted">Accepted</option>
                                            <option value="rejected">Rejected</option>
                                        </select>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default BuilderApplications;
