import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { useSelector } from 'react-redux';

const SecurityContext = createContext();

export const SecurityProvider = ({ children }) => {
    const [isLocked, setIsLocked] = useState(false);
    const [failedAttempts, setFailedAttempts] = useState(0);
    const [lockoutUntil, setLockoutUntil] = useState(null);
    const user = useSelector(state => state.auth.user);

    const LOCKOUT_DURATION = 15 * 60 * 1000; // 15 minutes
    const MAX_ATTEMPTS = 3;

    // Auto-lock after 10 mins of inactivity
    useEffect(() => {
        if (!user || isLocked) return;

        let timeout;
        const resetTimer = () => {
            clearTimeout(timeout);
            timeout = setTimeout(() => {
                setIsLocked(true);
            }, 5 * 60 * 1000); // 5 minutes
        };

        window.addEventListener('mousemove', resetTimer);
        window.addEventListener('keydown', resetTimer);
        resetTimer();

        return () => {
            window.removeEventListener('mousemove', resetTimer);
            window.removeEventListener('keydown', resetTimer);
            clearTimeout(timeout);
        };
    }, [user, isLocked]);

    const unlock = useCallback((providedPin) => {
        // In a real system, this would be a secondary password or PIN stored in DB
        // For this expert setup, we'll use '1234' as the initial vault key 
        // to show functionality, but suggest users change it.
        const VAULT_KEY = "1234"; 

        if (lockoutUntil && Date.now() < lockoutUntil) {
            return { success: false, message: `System locked. Try again in ${Math.ceil((lockoutUntil - Date.now()) / 60000)} mins.` };
        }

        if (providedPin === VAULT_KEY) {
            setIsLocked(false);
            setFailedAttempts(0);
            setLockoutUntil(null);
            return { success: true };
        } else {
            const nextAttempts = failedAttempts + 1;
            setFailedAttempts(nextAttempts);
            
            if (nextAttempts >= MAX_ATTEMPTS) {
                const until = Date.now() + LOCKOUT_DURATION;
                setLockoutUntil(until);
                return { success: false, message: "Maximum attempts reached. System Lockdown initiated." };
            }
            
            return { success: false, message: `Incorrect key. ${MAX_ATTEMPTS - nextAttempts} attempts remaining.` };
        }
    }, [failedAttempts, lockoutUntil]);

    const lock = () => setIsLocked(true);

    return (
        <SecurityContext.Provider value={{ isLocked, unlock, lock, failedAttempts, lockoutUntil }}>
            {children}
        </SecurityContext.Provider>
    );
};

export const useSecurity = () => useContext(SecurityContext);
