import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { supabaseService } from '../services/supabaseService';
import Header from '../components/ui/Header';
import Footer from '../components/ui/Footer';
import Icon from '../components/AppIcon';
import Button from '../components/ui/Button';
import { useToast } from '../contexts/ToastContext';

const ROLES = [
    { 
        id: 'dev', 
        title: 'Tech Architect', 
        desc: 'Build the core engines of LUC. React, Node.js, and Supabase wizards.', 
        icon: 'Code2', 
        color: 'text-blue-500', 
        bg: 'bg-blue-500/10' 
    },
    { 
        id: 'design', 
        title: 'UI/UX Visionary', 
        desc: 'Craft the elite aesthetics and seamless experiences of the Hub.', 
        icon: 'Palette', 
        color: 'text-purple-500', 
        bg: 'bg-purple-500/10' 
    },
    { 
        id: 'content', 
        title: 'Creative Evangelist', 
        desc: 'Tell the LUC story. Content creators, writers, and brand builders.', 
        icon: 'PenTool', 
        color: 'text-orange-500', 
        bg: 'bg-orange-500/10' 
    },
    { 
        id: 'community', 
        title: 'Ecosystem Manager', 
        desc: 'Scale the community. Engagement experts and growth hackers.', 
        icon: 'Users', 
        color: 'text-emerald-500', 
        bg: 'bg-emerald-500/10' 
    }
];

const JoinTheBuild = () => {
    const { addToast } = useToast();
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [selectedRole, setSelectedRole] = useState('dev');

    const handleSubmit = async (e) => {
        e.preventDefault();
        setIsSubmitting(true);
        const formData = new FormData(e.target);
        
        const applicationData = {
            full_name: formData.get('name'),
            email: formData.get('email'),
            role: selectedRole,
            portfolio_url: formData.get('portfolio'),
            reason: formData.get('reason'),
            location: 'Yobe State',
            status: 'pending'
        };

        try {
            // We'll create a table for this or use a general contact table
            const { error } = await supabaseService.submitBuilderApplication(applicationData);
            if (error) throw error;
            
            addToast("Application submitted! We'll review your portfolio.", "success");
            e.target.reset();
        } catch (err) {
            addToast("Failed to submit. Please try again.", "error");
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="min-h-screen bg-background flex flex-col font-sans selection:bg-primary/30">
            <Header />
            
            <main className="flex-1">
                {/* Hero Section */}
                <section className="relative pt-24 pb-32 overflow-hidden">
                    <div className="absolute inset-0 bg-slate-900 z-0" />
                    <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-20 z-0" />
                    <div className="absolute top-0 right-0 w-[800px] h-[800px] bg-primary/10 rounded-full blur-[120px] -translate-y-1/2 translate-x-1/3 pointer-events-none" />
                    
                    <div className="max-w-[1400px] mx-auto px-6 relative z-10">
                        <div className="max-w-3xl space-y-8">
                            <motion.div
                                initial={{ opacity: 0, x: -20 }}
                                animate={{ opacity: 1, x: 0 }}
                                className="flex items-center gap-3"
                            >
                                <div className="h-1 w-12 bg-primary rounded-full" />
                                <span className="text-[10px] font-black uppercase tracking-[0.4em] text-primary">Join the Elite Build Team</span>
                            </motion.div>

                            <motion.h1 
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: 0.1 }}
                                className="text-5xl md:text-8xl font-black text-white italic tracking-tighter uppercase leading-[0.9]"
                            >
                                Building the <span className="text-primary italic">Yobe Tech</span> Future.
                            </motion.h1>

                            <motion.p 
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: 0.2 }}
                                className="text-xl text-slate-400 font-medium leading-relaxed max-w-2xl"
                            >
                                We are looking for the top 1% of developers, designers, and creators in Yobe State to co-architect the LUC Academy ecosystem. No resumes—only your craft.
                            </motion.p>
                        </div>
                    </div>
                </section>

                {/* Roles Grid */}
                <section className="max-w-[1400px] mx-auto px-6 -mt-20 relative z-20">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                        {ROLES.map((role, idx) => (
                            <motion.div
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: 0.3 + (idx * 0.1) }}
                                key={role.id}
                                onClick={() => setSelectedRole(role.id)}
                                className={`p-8 bg-card border-2 rounded-[2.5rem] cursor-pointer transition-all duration-500 shadow-xl ${selectedRole === role.id ? 'border-primary ring-4 ring-primary/10 -translate-y-4' : 'border-transparent hover:border-primary/20'}`}
                            >
                                <div className={`p-4 ${role.bg} ${role.color} w-fit rounded-2xl mb-6`}>
                                    <Icon name={role.icon} size={32} />
                                </div>
                                <h3 className="text-xl font-black italic tracking-tight uppercase mb-3">{role.title}</h3>
                                <p className="text-sm text-slate-500 font-medium leading-relaxed">{role.desc}</p>
                            </motion.div>
                        ))}
                    </div>
                </section>

                {/* Application Form */}
                <section className="max-w-4xl mx-auto px-6 py-32 space-y-16">
                    <div className="text-center space-y-4">
                        <h2 className="text-4xl font-black italic tracking-tighter uppercase">Submit Your <span className="text-primary">Portfolio.</span></h2>
                        <p className="text-slate-500 font-bold italic uppercase tracking-widest text-xs">Applications for the Q3 Build Cycle are now open.</p>
                    </div>

                    <form onSubmit={handleSubmit} className="bg-card border border-border rounded-[3rem] p-8 md:p-16 shadow-2xl space-y-10">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-primary/60 ml-2">Full Name</label>
                                <input name="name" required placeholder="John Doe" className="w-full bg-slate-100 dark:bg-white/5 border-none rounded-2xl p-4 font-bold focus:ring-2 focus:ring-primary outline-none transition-all" />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-primary/60 ml-2">Email Address</label>
                                <input type="email" name="email" required placeholder="john@example.com" className="w-full bg-slate-100 dark:bg-white/5 border-none rounded-2xl p-4 font-bold focus:ring-2 focus:ring-primary outline-none transition-all" />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-primary/60 ml-2">Portfolio / GitHub / LinkedIn URL</label>
                            <input name="portfolio" required placeholder="https://..." className="w-full bg-slate-100 dark:bg-white/5 border-none rounded-2xl p-4 font-bold focus:ring-2 focus:ring-primary outline-none transition-all" />
                        </div>

                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-primary/60 ml-2">Why do you want to build LUC Hub?</label>
                            <textarea name="reason" rows="4" required placeholder="Tell us about your mission..." className="w-full bg-slate-100 dark:bg-white/5 border-none rounded-2xl p-4 font-bold focus:ring-2 focus:ring-primary outline-none transition-all resize-none" />
                        </div>

                        <div className="pt-6">
                            <button 
                                disabled={isSubmitting}
                                className="w-full py-6 bg-primary text-white font-black italic text-xl rounded-[2rem] shadow-2xl shadow-primary/30 hover:scale-[1.02] active:scale-[0.98] transition-all flex items-center justify-center gap-4"
                            >
                                {isSubmitting ? (
                                    <Icon name="RefreshCw" className="animate-spin" />
                                ) : (
                                    <>
                                        JOIN THE BUILD
                                        <Icon name="ArrowRight" size={24} />
                                    </>
                                )}
                            </button>
                        </div>
                    </form>
                </section>
            </main>

            <Footer />
        </div>
    );
};

export default JoinTheBuild;
