import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import Modal from '../../../components/ui/Modal';
import Button from '../../../components/ui/Button';
import Icon from '../../../components/AppIcon';
import { cn } from '../../../utils/cn';
import { supabaseService } from '../../../services/supabaseService';
import { useToast } from '../../../contexts/ToastContext';
import { formatLuc, formatNaira, nairaToLuc } from '../../../utils/currencyUtils';
import IntegrityAgreementModal from './IntegrityAgreementModal';

const PaymentModal = ({ isOpen, onClose, course, onPaymentSuccess }) => {
    const { user } = useSelector((state) => state.auth);
    const { addToast } = useToast();
    const [step, setStep] = useState('checkout'); // checkout -> processing -> success
    const [isLoading, setIsLoading] = useState(false);
    const [wallet, setWallet] = useState({ balance: 0 });
    const [isFetchingWallet, setIsFetchingWallet] = useState(false);
    const [showIntegrityModal, setShowIntegrityModal] = useState(false);

    useEffect(() => {
        if (isOpen && user?.id) {
            fetchUserWallet();
        }
    }, [isOpen, user?.id]);

    const fetchUserWallet = async () => {
        setIsFetchingWallet(true);
        try {
            const data = await supabaseService.getUserWallet(user.id);
            setWallet(data);
        } catch (error) {
            console.error("Failed to fetch wallet:", error);
        } finally {
            setIsFetchingWallet(false);
        }
    };

    const handlePaystackPayment = () => {
        if (!user || !user.email) {
            alert('Please log in to complete payment');
            return;
        }

        setIsLoading(true);

        const handler = window.PaystackPop.setup({
            key: import.meta.env.VITE_PAYSTACK_PUBLIC_KEY || 'pk_test_placeholder', // Use your real key in .env
            email: user.email,
            amount: course.price * 100, // Paystack uses kobo/cents
            currency: 'NGN',
            callback: (response) => {
                // Payment successful
                setStep('processing');
                setTimeout(() => {
                    setStep('success');
                    onPaymentSuccess(course, response.reference);
                }, 2000);
            },
            onClose: () => {
                setIsLoading(false);
            }
        });

        handler.openIframe();
    };

    const handleLucPayment = async () => {
        // Check for integrity agreement first
        const hasAccepted = localStorage.getItem(`luc_integrity_accepted_${user.id}`);
        if (!hasAccepted) {
            setShowIntegrityModal(true);
            return;
        }

        const lucPrice = nairaToLuc(course.price);
        
        if (wallet.balance < lucPrice) {
            addToast("Insufficient LUC Credits. Earn more by completing courses!", "warning");
            return;
        }

        setIsLoading(true);
        try {
            const result = await supabaseService.processWalletTransaction(
                user.id,
                -lucPrice,
                'course_purchase',
                `Purchased course: ${course.title}`,
                `purchase_${course.id}`
            );

            if (result.success) {
                setStep('processing');
                setTimeout(() => {
                    setStep('success');
                    onPaymentSuccess(course, `LUC_${Date.now()}`);
                }, 1500);
            } else {
                addToast(result.error || "Payment failed", "error");
                setIsLoading(false);
            }
        } catch (error) {
            console.error("LUC Payment Error:", error);
            addToast("An error occurred during transaction", "error");
            setIsLoading(false);
        }
    };

    const handleAcceptIntegrity = () => {
        localStorage.setItem(`luc_integrity_accepted_${user.id}`, 'true');
        setShowIntegrityModal(false);
        handleLucPayment(); // Proceed with payment after acceptance
    };

    useEffect(() => {
        if (!isOpen) {
            setStep('checkout');
            setIsLoading(false);
        }
    }, [isOpen]);

    if (!course) return null;

    return (
        <>
        <Modal
            isOpen={isOpen}
            onClose={onClose}
            title={step === 'success' ? "Payment Confirmed!" : "Secure Checkout"}
            size="md"
        >
            <div className="space-y-6">
                {step === 'checkout' && (
                    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                        {/* Course Recap */}
                        <div className="flex gap-4 p-6 bg-slate-900 border border-white/10 rounded-[2rem] mb-8 relative overflow-hidden group">
                            <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
                                <Icon name="ShieldCheck" size={60} />
                            </div>
                            <div className="w-24 h-24 rounded-2xl overflow-hidden shrink-0 border border-white/5 shadow-xl">
                                <img src={course.image || course.thumbnail} alt={course.title} className="w-full h-full object-cover" />
                            </div>
                            <div className="flex flex-col justify-center">
                                <h4 className="font-black text-white text-lg line-clamp-1 italic">{course.title}</h4>
                                <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mb-2">{course.instructor}</p>
                                <span className="text-2xl font-black text-secondary italic">₦{course.price?.toLocaleString()}</span>
                            </div>
                        </div>

                        {/* Paystack Trigger */}
                        <div className="space-y-6">
                            <div className="p-4 bg-secondary/5 border border-secondary/20 rounded-2xl flex items-center gap-3">
                                <div className="w-10 h-10 rounded-full bg-secondary/10 flex items-center justify-center text-secondary">
                                    <Icon name="Lock" size={18} />
                                </div>
                                <p className="text-[10px] text-secondary font-black uppercase tracking-widest leading-relaxed">
                                    Secured by Paystack • PCI-DSS Compliant
                                </p>
                            </div>

                            <div className="grid grid-cols-1 gap-3">
                                <Button
                                    fullWidth
                                    onClick={handlePaystackPayment}
                                    loading={isLoading}
                                    className="h-16 text-lg font-black italic bg-primary hover:bg-primary/90 text-white shadow-2xl shadow-primary/20 rounded-2xl"
                                >
                                    PAY WITH CARD
                                </Button>

                                <div className="relative flex items-center py-2">
                                    <div className="flex-grow border-t border-border"></div>
                                    <span className="flex-shrink mx-4 text-[10px] font-black uppercase tracking-widest text-muted-foreground">OR</span>
                                    <div className="flex-grow border-t border-border"></div>
                                </div>

                                <Button
                                    fullWidth
                                    variant="outline"
                                    onClick={handleLucPayment}
                                    loading={isLoading}
                                    disabled={wallet.balance < nairaToLuc(course.price)}
                                    className="h-16 border-indigo-500/30 hover:bg-indigo-500/5 text-indigo-500 rounded-2xl flex flex-col items-center justify-center py-2"
                                >
                                    <span className="text-sm font-black italic uppercase tracking-widest">Pay with {nairaToLuc(course.price)} LUC</span>
                                    <span className="text-[10px] font-medium opacity-70">
                                        Your Balance: {formatLuc(wallet.balance)}
                                    </span>
                                </Button>
                            </div>

                            <div className="flex items-center justify-center gap-6 opacity-30 grayscale hover:grayscale-0 transition-all">
                                <img src="https://upload.wikimedia.org/wikipedia/commons/2/2a/Mastercard-logo.svg" alt="Mastercard" className="h-6" />
                                <img src="https://upload.wikimedia.org/wikipedia/commons/5/5e/Visa_Inc._logo.svg" alt="Visa" className="h-4" />
                                <img src="https://paystack.com/assets/payment-logos/verve.svg" alt="Verve" className="h-5" />
                            </div>
                        </div>
                    </div>
                )}

                {step === 'processing' && (
                    <div className="py-12 flex flex-col items-center justify-center text-center animate-in fade-in duration-500">
                        <div className="relative w-24 h-24 mb-8">
                            <div className="absolute inset-0 border-4 border-secondary/20 rounded-full" />
                            <div className="absolute inset-0 border-4 border-secondary rounded-full border-t-transparent animate-spin" />
                            <div className="absolute inset-0 flex items-center justify-center text-secondary">
                                <Icon name="ShieldCheck" size={40} />
                            </div>
                        </div>
                        <h3 className="text-2xl font-black italic text-primary mb-2">Authenticating...</h3>
                        <p className="text-muted-foreground max-w-xs mx-auto text-sm">
                            We are securely processing your transaction with your bank. Please do not close this window.
                        </p>
                    </div>
                )}

                {step === 'success' && (
                    <div className="py-8 flex flex-col items-center justify-center text-center animate-in zoom-in-95 duration-500">
                        <div className="w-24 h-24 bg-success/20 rounded-full flex items-center justify-center text-success mb-8 scale-110">
                            <Icon name="CheckCircle" size={48} />
                        </div>
                        <h3 className="text-3xl font-black italic text-primary mb-2">You're Enrolled!</h3>
                        <p className="text-muted-foreground mb-10 max-w-xs mx-auto">
                            The full curriculum of <span className="text-primary font-bold italic">"{course.title}"</span> is now unlocked and available in your library.
                        </p>
                        <Button
                            fullWidth
                            className="bg-success hover:bg-success/90 h-14 font-black italic"
                            onClick={() => onPaymentSuccess(course)}
                            iconName="ArrowRight"
                            iconPosition="right"
                        >
                            GO TO CLASSROOM
                        </Button>
                    </div>
                )}
            </div>
        </Modal>

        <IntegrityAgreementModal 
            isOpen={showIntegrityModal}
            onClose={() => setShowIntegrityModal(false)}
            onAccept={handleAcceptIntegrity}
        />
        </>
    );
};

export default PaymentModal;
