import React, { useState, useEffect } from 'react';
import { useSecurity } from '../../contexts/SecurityContext';

const GlobalLockOverlay = () => {
    const { isLocked, unlock, lockoutUntil } = useSecurity();
    const [pin, setPin] = useState('');
    const [error, setError] = useState('');
    const [forceUpdate, setForceUpdate] = useState(0);

    // Update timer if locked out
    useEffect(() => {
        if (lockoutUntil && Date.now() < lockoutUntil) {
            const interval = setInterval(() => setForceUpdate(prev => prev + 1), 1000);
            return () => clearInterval(interval);
        }
    }, [lockoutUntil]);

    useEffect(() => {
        if (pin.length === 4 && (!lockoutUntil || Date.now() >= lockoutUntil)) {
            const result = unlock(pin);
            if (!result.success) {
                setError(result.message);
                setPin('');
            } else {
                setError('');
            }
        }
    }, [pin, lockoutUntil, unlock]);

    // If not locked, return null
    if (!isLocked) return null;

    const handleUnlock = (e) => {
        e.preventDefault();
        const result = unlock(pin);
        if (!result.success) {
            setError(result.message);
            setPin('');
        } else {
            setError('');
        }
    };

    return (
        <div className="fixed inset-0 z-[9999] bg-black/90 backdrop-blur-md flex items-center justify-center pointer-events-auto transition-opacity duration-300">
            <div className="bg-gray-900 border border-gray-800 p-8 rounded-2xl shadow-[0_0_50px_rgba(225,29,72,0.15)] max-w-sm w-full relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-red-600 to-rose-400"></div>
                
                <h2 className="text-2xl font-bold text-white mb-2 text-center flex items-center justify-center gap-2">
                   <svg className="w-8 h-8 text-rose-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path></svg>
                   SYSTEM LOCKED
                </h2>
                
                <p className="text-gray-400 text-center mb-6 text-sm">
                    {lockoutUntil && Date.now() < lockoutUntil 
                        ? `Maximum attempts exceeded. Wait for timer: ${Math.ceil((lockoutUntil - Date.now()) / 1000)}s` 
                        : "Due to inactivity, please enter your authorization PIN to resume session."}
                </p>

                <form onSubmit={handleUnlock} className="space-y-4">
                    <div>
                        <input 
                            type="password" 
                            name="secret"
                            value={pin}
                            onChange={(e) => setPin(e.target.value)}
                            disabled={lockoutUntil && Date.now() < lockoutUntil}
                            className="w-full bg-black border border-gray-700 text-white rounded-lg px-4 py-3 text-center tracking-[0.75em] font-mono text-xl focus:border-rose-500 focus:ring-1 focus:ring-rose-500 outline-none transition-all disabled:opacity-50"
                            placeholder="••••"
                            maxLength={4}
                            autoComplete="off"
                        />
                    </div>
                    
                    {error && (
                        <p className="text-rose-400 text-sm text-center font-medium animate-pulse">{error}</p>
                    )}

                    <button 
                        type="submit"
                        disabled={pin.length < 4 || (lockoutUntil && Date.now() < lockoutUntil)}
                        className="w-full bg-gradient-to-r from-rose-600 to-red-500 hover:from-rose-500 hover:to-red-400 text-white font-bold py-3 px-4 rounded-lg shadow-[0_0_15px_rgba(225,29,72,0.4)] tracking-wider disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                    >
                        AUTHENTICATE
                    </button>
                    
                    <p className="text-center text-xs text-gray-500 mt-4">
                        * Default Vault PIN is 1234
                    </p>
                </form>
            </div>
        </div>
    );
};

export default GlobalLockOverlay;
