import React, { useEffect } from 'react';
import { createPortal } from 'react-dom';
import Icon from '../AppIcon';
import Button from './Button';
import { cn } from '../../utils/cn';

const Modal = ({
    isOpen,
    onClose,
    title,
    children,
    footer,
    size = 'md',
    showClose = true,
    className,
    isLocal = false
}) => {
    // Prevent scrolling when modal is open
    useEffect(() => {
        if (isLocal) return; // Skip for local modals
        if (isOpen) {
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = 'unset';
        }
        return () => {
            document.body.style.overflow = 'unset';
        };
    }, [isOpen, isLocal]);

    // Handle ESC key
    useEffect(() => {
        const handleEsc = (e) => {
            if (e.key === 'Escape') onClose();
        };
        window.addEventListener('keydown', handleEsc);
        return () => window.removeEventListener('keydown', handleEsc);
    }, [onClose]);

    if (!isOpen) return null;

    const sizeClasses = {
        sm: 'max-w-sm',
        md: 'max-w-md',
        lg: 'max-w-lg',
        xl: 'max-w-2xl',
        full: 'max-w-[95vw]'
    };

    const modalContent = (
        <div className={cn(
            isLocal ? "absolute inset-0 z-[50]" : "fixed inset-0 z-[200]",
            "flex items-center justify-center p-4"
        )}>
            {/* Backdrop */}
            <div
                className="absolute inset-0 bg-background/80 backdrop-blur-sm animate-in fade-in duration-300"
                onClick={onClose}
            />

            {/* Modal Content */}
            <div className={cn(
                "relative bg-card border border-border rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 w-full flex flex-col max-h-[90vh]",
                // Responsive max-widths: on mobile, almost full width; on desktop, follow size
                size === 'sm' && 'md:max-w-sm w-[95vw]',
                size === 'md' && 'md:max-w-md w-[95vw]',
                size === 'lg' && 'md:max-w-lg w-[95vw]',
                size === 'xl' && 'md:max-w-2xl w-[95vw]',
                size === 'full' && 'max-w-[95vw]',
                className
            )}>
                {/* Header */}
                <div className="flex items-center justify-between p-4 border-b border-border shrink-0">
                    <h2 className="text-lg font-bold text-primary">{title}</h2>
                    {showClose && (
                        <button
                            onClick={onClose}
                            className="p-2 hover:bg-muted rounded-full transition-colors text-muted-foreground hover:text-primary"
                        >
                            <Icon name="X" size={18} />
                        </button>
                    )}
                </div>

                {/* Body */}
                <div className="p-4 overflow-y-auto flex-1 custom-scrollbar relative">
                    {children}
                </div>

                {/* Footer */}
                {footer && (
                    <div className="flex justify-end gap-3 p-4 border-t border-border bg-muted/20 shrink-0">
                        {footer}
                    </div>
                )}
            </div>
        </div>
    );

    if (isLocal) return modalContent;

    return createPortal(modalContent, document.body);
};

export default Modal;
